public struct FfiFrame {
    public var timestampS: Double
    public var pose: FfiPose
    public var tracking: FfiTracking
    public var blurScore: Float
    public var exposureClipRatio: Float
    public var medianDepthM: Float
    public var angularVelocityRadS: Float
    public var sparsePointCount: UInt32
    public var lux: Float

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(timestampS: Double, pose: FfiPose, tracking: FfiTracking, blurScore: Float, exposureClipRatio: Float, medianDepthM: Float, angularVelocityRadS: Float, sparsePointCount: UInt32, lux: Float) {
        self.timestampS = timestampS
        self.pose = pose
        self.tracking = tracking
        self.blurScore = blurScore
        self.exposureClipRatio = exposureClipRatio
        self.medianDepthM = medianDepthM
        self.angularVelocityRadS = angularVelocityRadS
        self.sparsePointCount = sparsePointCount
        self.lux = lux
    }
}



extension FfiFrame: Equatable, Hashable {
    public static func ==(lhs: FfiFrame, rhs: FfiFrame) -> Bool {
        if lhs.timestampS != rhs.timestampS {
            return false
        }
        if lhs.pose != rhs.pose {
            return false
        }
        if lhs.tracking != rhs.tracking {
            return false
        }
        if lhs.blurScore != rhs.blurScore {
            return false
        }
        if lhs.exposureClipRatio != rhs.exposureClipRatio {
            return false
        }
        if lhs.medianDepthM != rhs.medianDepthM {
            return false
        }
        if lhs.angularVelocityRadS != rhs.angularVelocityRadS {
            return false
        }
        if lhs.sparsePointCount != rhs.sparsePointCount {
            return false
        }
        if lhs.lux != rhs.lux {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(timestampS)
        hasher.combine(pose)
        hasher.combine(tracking)
        hasher.combine(blurScore)
        hasher.combine(exposureClipRatio)
        hasher.combine(medianDepthM)
        hasher.combine(angularVelocityRadS)
        hasher.combine(sparsePointCount)
        hasher.combine(lux)
    }
}


