    typealias SwiftType = FfiDecision

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiDecision {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .accept
        
        case 2: return .rejectBlurry
        
        case 3: return .rejectExposure
        
        case 4: return .rejectTracking
        
        case 5: return .rejectTooSimilar
        
        case 6: return .rejectCapReached
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiDecision, into buf: inout [UInt8]) {
        switch value {
        
        
        case .accept:
            writeInt(&buf, Int32(1))
        
        
        case .rejectBlurry:
            writeInt(&buf, Int32(2))
        
        
        case .rejectExposure:
            writeInt(&buf, Int32(3))
        
        
        case .rejectTracking:
            writeInt(&buf, Int32(4))
        
        
        case .rejectTooSimilar:
            writeInt(&buf, Int32(5))
        
        
        case .rejectCapReached:
            writeInt(&buf, Int32(6))
        
        }
    }
